-- =========================================================
-- bot.png - 千星奇域图元拟合拼图
-- 由 Miliastra-toolbox-primitive-shape 自动导出
-- 模式: outline | 图元数: 161 (背景 0) | 原图: 375x375
-- =========================================================
--
-- ======================== 使用说明 ========================
-- 本脚本运行时在玩家界面上用多个图片控件拼出拟合图案，
-- 每个图元 = 一个图片控件（方块/圆/三角之一 + 纯色染色）。
--
-- 第 1 步：准备图片控件模板（只需做一次）
--   1. 打开「界面控件组库 -> 客户端控件模板」，新建图片控件模板，
--      建议直接建在客户端控件容器下并「仅存为模板」（不要挂到主屏）。
--   2. 分别准备三种形状模板，并在检视器中绑定对应图片资产：
--        实心方块   -> 方形纯色素材
--        实心圆形   -> 圆形纯色素材 (通过非等比拉伸变成椭圆)
--        实心三角形 -> 三角形纯色素材
--      显示模式设为「拉伸」(Stretch)；颜色不用管，脚本会逐图元染色。
--   3. 点击每个模板查看其「控件模板索引ID」，填到下方
--      PREFAB_ID_BY_KIND 对应项。注意这是控件模板索引，
--      不是图片资产 ID，也不是运行时实例 ID。
--
-- 第 2 步：挂载脚本
--   把本文件关联为客户端脚本，挂到「客户端控件容器」（或任一
--   客户端控件）上。脚本以挂载控件为父节点创建全部图元，
--   图案中心默认对齐父控件中心。
--
-- 第 3 步：按需调整下方「可调参数」
--   BASE_SCALE      整体缩放倍率，1 = 原图像素尺寸
--   FIT_TO_CANVAS   true 时若图案超出画布会自动缩小到 CANVAS_MARGIN 内
--   OFFSET_X/Y      相对父控件中心的偏移(UI 像素，Y 向上)
--   SKIP_BACKGROUND true 时跳过填充模式自动加的白色背景矩形
--
-- 运行时机与生命周期
--   控件创建发生在 OnStart()。官方接口在 OnInit 阶段尚不可用
--   （实测返回 nil），请勿把创建逻辑挪到 OnInit。
--   脚本重复启用时会先销毁上一次创建的全部图元再重建。
--
-- 已知边界
--   * 运行时控件总数 = 图元数量，注意经典/超限模式的画布控件上限，
--     图元过多时请先在网页端减少图元数量或改用 GIA 导入路线；
--   * 三角形以质心为轴心旋转(0.5, 1/3)，与网页预览行为一致；
--     若实际绑定的三角形素材朝向不同，请调整 ROTATION_BIAS 或换素材；
--   * 脚本未调用 SetImage 动态换图（图片来源枚举待验证），
--     形状差异全部通过预绑定模板区分，稳定性更好。
-- =========================================================
-- ====================== 可调参数 ==========================

-- 图片控件模板索引ID（TODO 必填：把 0 改成编辑器里查到的索引）
local PREFAB_ID_BY_KIND = {
    [0] = 0, -- 实心方块 (本图未用到)
    [1] = 0, -- 实心圆形(可拉伸成椭圆) <-- TODO 必填
    [2] = 0, -- 实心三角形 (本图未用到)
}

local BASE_SCALE = 1.0 -- 整体缩放倍率
local FIT_TO_CANVAS = true -- 超出画布时自动缩小
local CANVAS_MARGIN = 0.9 -- 自适应时占画布宽高比例的上限
local OFFSET_X = 0 -- 图案中心相对父控件中心的水平偏移
local OFFSET_Y = 0 -- 图案中心相对父控件中心的竖直偏移(Y 向上)
local SKIP_BACKGROUND = false -- true 时跳过下面的背景图元
local ROTATION_BIAS = 0 -- 全局附加旋转角(度)，一般保持 0

